// NASA_ORRERY_DATA: exact rows from the supplied NASA ontology-based orrery.
// https://nasa.github.io/mission-viz/RMarkdown/ontology_based_orrery_generated_from_R_code.html
// Fields in source order: eccentricity, inclination, omega, period, raan, sma, tau.
// sma is in AU; period in days. Source angle conventions are retained verbatim.
// Rendering uses sma, eccentricity, period only; no undocumented epoch is assumed.
const NASA_ORRERY_DATA = {
  Mercury:{eccentricity:0.20563,inclination:3.38,omega:48.331,period:88.0,raan:281.01,sma:0.387098,tau:29.124},
  Venus:{eccentricity:0.006772,inclination:3.86,omega:76.68,period:224.701,raan:272.76,sma:0.723332,tau:54.884},
  Earth:{eccentricity:0.016708,inclination:7.155,omega:-11.26064,period:365.25638,raan:23.439281,sma:1.0,tau:114.20783},
  Mars:{eccentricity:0.0934,inclination:5.65,omega:49.558,period:686.971,raan:317.68143,sma:1.523679,tau:286.502},
  Jupiter:{eccentricity:0.0489,inclination:6.09,omega:100.464,period:4332.59,raan:268.057,sma:5.2044,tau:273.867},
  Saturn:{eccentricity:0.0565,inclination:5.51,omega:113.665,period:10759.22,raan:40.589,sma:9.5826,tau:339.392},
  Uranus:{eccentricity:0.046381,inclination:6.48,omega:74.006,period:30688.5,raan:257.311,sma:19.2184,tau:96.998856},
  Neptune:{eccentricity:0.009456,inclination:6.43,omega:131.784,period:60182.0,raan:299.3,sma:30.110388,tau:276.336},
  Pluto:{eccentricity:0.2488,inclination:11.88,omega:110.299,period:90560.0,raan:132.993,sma:39.48,tau:113.834}
};
// Exact diameter (km), gravity (m/s²), mean temperature (°C), magnetic field rows:
// https://nssdc.gsfc.nasa.gov/planetary/factsheet/ . Not new measurements by a player.
const NASA_FACTS={Mercury:[4879,3.7,167,'Yes'],Venus:[12104,8.9,464,'No'],Mars:[6792,3.7,-65,'No'],Jupiter:[142984,23.1,-110,'Yes'],Saturn:[120536,9,-140,'Yes'],Uranus:[51118,8.7,-195,'Yes'],Neptune:[49528,11,-200,'Yes'],Pluto:[2376,0.6,-225,'Unknown']};
const SOURCES={orrery:'https://nasa.github.io/mission-viz/RMarkdown/ontology_based_orrery_generated_from_R_code.html',facts:'https://nssdc.gsfc.nasa.gov/planetary/factsheet/',science:'https://science.nasa.gov/solar-system/',data:'https://planetary.data.nasa.gov/find-data',trajectory:'https://trajbrowser.arc.nasa.gov/traj_browser.php'};
// GAME_BALANCE contains invented educational units, never NASA performance data or dollars.
// Range checks use AU-distance proxies. Thrust/weight use compatible abstract force units.
const GAME_BALANCE={budgets:[100,100,110,160,180,210,230,250],bonus:15,holdSeconds:5,
 fuel:[{name:'Compact tank',cost:15,weight:12,range:1},{name:'Extended tank',cost:32,weight:24,range:10},{name:'Deep-space tank',cost:52,weight:36,range:45}],
 engine:[{name:'Light engine',cost:20,weight:10,thrust:45},{name:'Heavy-lift engine',cost:38,weight:18,thrust:95},{name:'High-capacity engine',cost:55,weight:24,thrust:150}],
 satellite:[{name:'Compact orbiter',cost:15,weight:10},{name:'Survey orbiter',cost:24,weight:18},{name:'Research orbiter',cost:35,weight:26}],
 instruments:[{name:'Imaging camera',cost:12,weight:5,kind:'camera'},{name:'Thermal radiometer',cost:16,weight:7,kind:'thermal'},{name:'Magnetometer',cost:14,weight:6,kind:'magnetic'}]};
const WORLDS=[['Mercury','Rocky planet','#a5a2a8','Cratered terrain and a world of extreme temperatures.','Surface imaging · Thermal observations'],['Venus','Rocky planet','#d6ac67','Explore a cloud-covered world with a dense atmosphere.','Atmospheric observations · Thermal data'],['Mars','Rocky planet','#e28761','A rocky world. A new perspective. Map the surface and investigate its environment.','Surface mapping · Thermal observations'],['Jupiter','Gas giant','#cca68c','Investigate a giant planet through cloud imagery and magnetic observations.','Cloud imaging · Magnetic fields'],['Saturn','Gas giant','#dac38d','Observe a ringed gas giant and investigate its environment.','Ring imaging · Magnetic fields'],['Uranus','Ice giant','#8ad4d4','Explore an ice giant through atmospheric and magnetic observations.','Atmospheric imaging · Magnetic fields'],['Neptune','Ice giant','#658de4','Study a distant ice giant and its atmospheric environment.','Cloud imaging · Thermal observations'],['Pluto','Dwarf planet','#bea99e','Look beyond the planets to an icy dwarf world.','Surface imaging · Thermal observations']];
// World descriptions are educational summaries of NASA Solar System Exploration.
let selected='Mars',step=0,parts={fuel:0,engine:0,satellite:0,instruments:[0]},history=[];
try{history=JSON.parse(localStorage.getItem('orbit-foundry-flights')||'[]');if(!Array.isArray(history))history=[];history=history.filter(x=>x&&WORLDS.some(w=>w[0]===x.planet)&&typeof x.date==='string').slice(-50)}catch{}
let frame=0,game=null,keys={},transitioning=false;
const $=s=>document.querySelector(s),world=()=>WORLDS.find(w=>w[0]===selected),bonus=()=>history.length*GAME_BALANCE.bonus;
const fmt=n=>n.toLocaleString('en-US',{maximumFractionDigits:3});
// A mean-orbit same-side separation proxy, NOT current separation or flight path length.
const distance=name=>Math.abs(NASA_ORRERY_DATA[name].sma-NASA_ORRERY_DATA.Earth.sma);
const budget=()=>GAME_BALANCE.budgets[WORLDS.findIndex(w=>w[0]===selected)]+bonus();
function total(){const p=[GAME_BALANCE.fuel[parts.fuel],GAME_BALANCE.engine[parts.engine],GAME_BALANCE.satellite[parts.satellite],...parts.instruments.map(i=>GAME_BALANCE.instruments[i])];return{cost:p.reduce((s,v)=>s+v.cost,0),weight:p.reduce((s,v)=>s+v.weight,0),range:p[0].range,thrust:p[1].thrust}}
function checks(){const t=total();return[{ok:t.cost<=budget(),title:'Budget',value:`${t.cost} / ${budget()} credits`,reason:`Over budget by ${t.cost-budget()} credits. Reduce component costs.`},{ok:t.range>=distance(selected),title:'Fuel range',value:`${t.range} / ${fmt(distance(selected))} AU proxy`,reason:`Fuel depleted at ${Math.floor(t.range/distance(selected)*100)}% of the distance proxy. Choose a larger tank.`},{ok:t.thrust>=t.weight,title:'Thrust / weight',value:`${t.thrust} / ${t.weight} force units`,reason:`Thrust is ${t.weight-t.thrust} units below total weight. Choose a stronger engine or lighter payload.`},{ok:parts.instruments.length>0,title:'Science payload',value:`${parts.instruments.length} instrument${parts.instruments.length===1?'':'s'}`,reason:'Attach at least one scientific instrument.'}]}
function planet(canvas,name){const c=canvas.getContext('2d');canvas.width=96;canvas.height=80;c.imageSmoothingEnabled=false;const w=WORLDS.find(w=>w[0]===name),color=w?w[2]:'#6dafe4',r=name==='Saturn'?23:29;c.clearRect(0,0,96,80);if(name==='Saturn'){c.strokeStyle='#877254';c.lineWidth=6;c.beginPath();c.ellipse(48,40,43,11,-.25,0,Math.PI*2);c.stroke()}for(let y=-r;y<r;y+=3)for(let x=-r;x<r;x+=3){if(x*x+y*y>r*r)continue;c.fillStyle=color;c.fillRect(48+x,40+y,3,3);const shade=(x/r+1)*.22+Math.max(0,(x*x+y*y)/(r*r)-.5)*.3;c.fillStyle=`rgba(5,9,25,${shade})`;c.fillRect(48+x,40+y,3,3);const noise=Math.sin(x*17.3+y*4.7);if((name==='Jupiter'||name==='Saturn')&&Math.floor((y+r)/7)%3===0||noise>.68){c.fillStyle=name==='Mars'?'#9e514a55':'#f6e1b530';c.fillRect(48+x,40+y,3,3)}}if(name==='Mars'){c.fillStyle='#ecd7c7';c.fillRect(39,11,15,3);c.fillRect(42,14,12,3)}if(name==='Jupiter'){c.fillStyle='#ae6258';c.fillRect(52,46,12,6)}if(name==='Saturn'){c.strokeStyle='#cbb789';c.lineWidth=4;c.beginPath();c.ellipse(48,40,43,11,-.25,0,Math.PI);c.stroke()}}
function rocket(c,x,y,angle=0,scale=1){c.save();c.translate(x,y);c.rotate(angle);c.scale(scale,scale);c.fillStyle='#adb9d5';c.fillRect(-7,-15,14,32);c.fillStyle='#eef2ff';c.fillRect(-4,-23,8,8);c.fillRect(-2,-27,4,4);c.fillStyle=world()[2];c.fillRect(-7,2,14,6);c.fillStyle='#6be0e1';c.fillRect(-4,-12,8,8);c.fillStyle='#7988c6';c.fillRect(-13,8,6,13);c.fillRect(7,8,6,13);if(parts.satellite>0){c.fillStyle='#6e8dd0';c.fillRect(-20,-3,12,6);c.fillRect(8,-3,12,6)}c.fillStyle='#b1a3ff';c.fillRect(-5,18,10,8+parts.engine*2);c.fillStyle='#ffe7a2';c.fillRect(-2,18,4,5);if(parts.instruments.includes(2)){c.fillStyle='#88f8dc';c.fillRect(9,-15,2,13)}c.restore()}
function render(){cancelAnimationFrame(frame);game=null;$('#archive-count').textContent=String(history.length).padStart(2,'0');$('#mission-number').textContent=String(history.length+1).padStart(3,'0');document.querySelectorAll('[data-step]').forEach(b=>{b.classList.toggle('active',+b.dataset.step===step);b.setAttribute('aria-current',+b.dataset.step===step?'step':'false')});if(step===0)destinations();if(step===1)lab();if(step===2)flightScreen();if(step===3)results()}
function go(s){if(transitioning)return;transitioning=true;$('#transition').classList.add('cover');setTimeout(()=>{step=s;render();$('#transition').classList.remove('cover');transitioning=false;},350)}
function destinations(){$('#screen').innerHTML=`<div class="section-heading"><div><h2>Where will curiosity take you?</h2><p>Select your destination to begin a new mission.</p></div><span class="tag">08 WORLDS · ENDLESS POSSIBILITIES</span></div><div class="destination-layout"><div><div class="planet-grid">${WORLDS.map((w,i)=>`<button class="planet-card ${w[0]===selected?'selected':''}" data-planet="${w[0]}" aria-pressed="${w[0]===selected}"><span class="idx">0${i+1}</span>${w[0]===selected?'<span class="selected-mark">⊕</span>':''}<canvas aria-label="Pixel art ${w[0]}"></canvas><h3>${w[0]}</h3><small>${w[1].toUpperCase()}</small><span class="difficulty">${i<3?'▰▱▱ · INNER SYSTEM':i<5?'▰▰▱ · OUTER SYSTEM':'▰▰▰ · DEEP SPACE'}</span></button>`).join('')}</div><div class="source-line"><span>◈ Orbital parameters: NASA ontology-based orrery<br>Planet sizes and distances are not shown to scale.</span><button class="notes">Explore the data ↗</button></div></div><aside class="planet-detail"><div class="label">DESTINATION BRIEFING</div><div class="detail-title"><h2>${selected}</h2><span>${world()[1].toUpperCase()}</span></div><canvas id="detail-planet" aria-label="${selected} pixel illustration"></canvas><p>${world()[3]}</p><div class="stats"><div><small>FROM EARTH · ESTIMATE</small><strong>${fmt(distance(selected))} <span style="font-size:11px">AU</span></strong><em>Mean-orbit separation proxy</em></div><div><small>MISSION BUDGET</small><strong>${budget()} <span style="font-size:11px">CR</span></strong><em>Game credits${bonus()?` · +${bonus()} sponsor bonus`:''}</em></div></div><div class="science-list"><div class="label">SCIENCE OPPORTUNITIES</div>${world()[4].split(' · ').map(s=>`<span>+ &nbsp;${s}</span>`).join('')}<span>+ &nbsp;Orbital & planetary properties</span></div><button class="primary" id="build">Build your rocket <span>↗</span></button></aside></div>`;document.querySelectorAll('[data-planet]').forEach(b=>{planet(b.querySelector('canvas'),b.dataset.planet);b.onclick=()=>{selected=b.dataset.planet;destinations()}});planet($('#detail-planet'),selected);$('#build').onclick=()=>go(1);$('.notes').onclick=notes}
function lab(){$('#screen').innerHTML=`<div class="section-heading"><div><h2>Your rocket. Your trade-offs.</h2><p>Configure four systems for ${selected}. Balance range, weight, and cost.</p></div><span class="tag">ASSEMBLY / ${selected.toUpperCase()}</span></div><div class="lab-layout"><div><div class="parts-grid">${[['fuel','01 · Fuel'],['engine','02 · Engine'],['satellite','03 · Satellite'],['instruments','04 · Scientific instruments']].map(([key,title])=>`<section class="panel"><h3>${title}</h3>${key==='instruments'?'<p class="help">Select one or more. Each unlocks a different finding.</p>':''}${GAME_BALANCE[key].map((p,i)=>`<button class="part ${(key==='instruments'?parts.instruments.includes(i):parts[key]===i)?'selected':''}" data-part="${key}" data-index="${i}" aria-pressed="${key==='instruments'?parts.instruments.includes(i):parts[key]===i}"><span>${p.name}<small>${p.weight} weight${p.range?` · ${p.range} AU range proxy`:''}${p.thrust?` · ${p.thrust} thrust`:''}</small></span><span>${p.cost} CR</span></button>`).join('')}</section>`).join('')}</div><div class="notice">EDUCATIONAL MODEL · All component ratings and credits are abstract game units. Range is a distance proxy; thrust and weight share a force scale. These are not real rocket specifications. <a href="${SOURCES.trajectory}" target="_blank" rel="noopener">Explore NASA trajectory planning ↗</a></div><button class="secondary" id="back">← Change destination</button></div><aside class="panel"><div class="label">LIVE ASSEMBLY</div><div class="rocket-stage"><canvas id="rocket-preview" aria-label="Your assembled rocket"></canvas></div><h3>${selected} orbital mission</h3><div class="budget-line">${total().cost} <span style="font-size:12px;color:var(--muted)">/ ${budget()} CR</span></div>${checks().map(c=>`<div class="check"><span>${c.ok?'✓':'×'} ${c.title}</span><span class="${c.ok?'pass':'fail'}">${c.value}</span></div>`).join('')}<button class="primary" id="launch">Run launch checks <span>↗</span></button><p class="help">Pass the engineering checks, navigate the flight, then hold the orbital zone for ${GAME_BALANCE.holdSeconds} seconds.</p><button class="secondary" id="demo">Quick judge loadout ✧</button></aside></div>`;const c=$('#rocket-preview');c.width=80;c.height=120;rocket(c.getContext('2d'),40,57,0,1.6);document.querySelectorAll('[data-part]').forEach(b=>b.onclick=()=>{let k=b.dataset.part,i=+b.dataset.index;if(k==='instruments'){parts.instruments=parts.instruments.includes(i)?parts.instruments.filter(x=>x!==i):[...parts.instruments,i]}else parts[k]=i;lab()});$('#back').onclick=()=>go(0);$('#launch').onclick=()=>{const fail=checks().filter(c=>!c.ok);if(fail.length)modal(`<div class="label">PRE-FLIGHT DIAGNOSTICS</div><h2>Mission held at the launch pad.</h2>${checks().map(c=>`<p class="${c.ok?'pass':'fail'}">${c.ok?'✓ '+c.title+' ready.':'× '+c.reason}</p>`).join('')}<p>Revise your assembly and try again. No credits have been spent.</p>`);else go(2)};$('#demo').onclick=()=>{parts={fuel:distance(selected)<=1?0:distance(selected)<=10?1:2,engine:distance(selected)<=1?0:1,satellite:0,instruments:[0]};lab()}}
function flightScreen(){$('#screen').innerHTML=`<div class="section-heading"><div><h2>Next stop: ${selected}.</h2><p>Steer your spacecraft. Avoid hazards. Establish a stable orbital pass.</p></div><span class="tag">FLIGHT / MANUAL CONTROL</span></div><div class="game-wrap"><div class="game-top"><span id="flight-status">READY FOR DEPARTURE</span><span id="flight-progress">TRANSIT 0%</span><span id="orbit-progress">ORBIT 0.0 / 5 s</span></div><canvas id="flight" width="1000" height="500" tabindex="0" aria-label="Flight game. Arrow keys or WASD to steer, P to pause. Hold the glowing orbital band for five seconds."></canvas><div class="game-bottom"><span>↑ ↓ ← → / WASD to steer · P to pause · Touch: use arrow buttons<br>Orbit inside the cyan band. Do not touch the planet.</span><div class="controls">${[['ArrowLeft','←'],['ArrowUp','↑'],['ArrowDown','↓'],['ArrowRight','→']].map(([k,v])=>`<button data-key="${k}" aria-label="Steer ${k.replace('Arrow','')}">${v}</button>`).join('')}</div><button class="secondary" id="pause">Start flight ▷</button></div></div><div class="notice">ARCADE FLIGHT · Time, obstacles, orbital capture, and visuals are compressed for play. No real transfer trajectory is implied. ${['Jupiter','Saturn','Pluto'].includes(selected)?'This route includes an arcade asteroid-belt encounter; this is not a physical belt around the destination.':'This route includes sparse arcade debris; no asteroid belt is depicted.'} Orbital diagram uses NASA eccentricity and period; its phase is illustrative.</div><div class="actions"><button class="secondary" id="return-lab">← Return to rocket lab</button><button class="secondary notes">View simulation rules ↗</button></div>`;$('#return-lab').onclick=()=>go(1);$('.notes').onclick=notes;startGame()}
function startGame(){const canvas=$('#flight'),c=canvas.getContext('2d');c.imageSmoothingEnabled=false;const far=WORLDS.findIndex(w=>w[0]===selected),belt=['Jupiter','Saturn','Pluto'].includes(selected),duration=12+far*1.2;game={x:90,y:250,t:0,orbit:0,last:0,paused:true,ended:false,hazards:[],spawn:0};const g=game,planetSprite=document.createElement('canvas');planet(planetSprite,selected);const stars=Array.from({length:85},(_,i)=>({x:(i*137.9)%1000,y:(i*87.3)%500}));function pause(){if(g.ended)return;g.paused=!g.paused;$('#pause').textContent=g.paused?'Resume ▷':'Pause Ⅱ';canvas.focus()}$('#pause').onclick=pause;document.querySelectorAll('[data-key]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();keys[b.dataset.key]=true;b.setPointerCapture(e.pointerId)};b.onpointerup=b.onpointercancel=()=>keys[b.dataset.key]=false});
 function end(success,reason){g.ended=true;keys={};if(success){const entry={planet:selected,date:new Date().toISOString(),instruments:[...parts.instruments]};history.push(entry);history=history.slice(-50);try{localStorage.setItem('orbit-foundry-flights',JSON.stringify(history))}catch{}go(3)}else{modal(`<div class="label">FLIGHT TELEMETRY / SIGNAL LOST</div><h2>Flight interrupted.</h2><p>${reason}</p><p>Your design passed the engineering model. No sponsor reward was awarded. Retry the flight or return to the lab.</p><div class="actions"><button class="primary" id="retry-flight">Retry flight ↗</button><button class="secondary" id="edit-flight">Edit rocket</button></div>`);$('#retry-flight').onclick=()=>{$('#modal').close();flightScreen()};$('#edit-flight').onclick=()=>{$('#modal').close();go(1)}}}
 function tick(time){if(game!==g)return;const dt=Math.min((time-(g.last||time))/1000,.04);g.last=time;if(!g.paused&&!g.ended){g.t+=dt;const dx=(keys.ArrowRight||keys.d?1:0)-(keys.ArrowLeft||keys.a?1:0),dy=(keys.ArrowDown||keys.s?1:0)-(keys.ArrowUp||keys.w?1:0);g.x=Math.max(18,Math.min(980,g.x+dx*230*dt));g.y=Math.max(25,Math.min(475,g.y+dy*230*dt));if(g.t<duration-2){g.spawn-=dt;if(g.spawn<=0){g.hazards.push({x:1040,y:35+Math.random()*430,r:9+Math.random()*12,speed:100+far*12,comet:far>4&&Math.random()>.7});g.spawn=belt?.55:1.55}}for(const h of g.hazards){h.x-=h.speed*dt;if(Math.hypot(h.x-g.x,h.y-g.y)<h.r+12){end(false,h.comet?'A comet crossed your flight path. Watch the bright tail and steer clear.':'Your spacecraft collided with debris. Use small steering adjustments to find a clear corridor.');return}}g.hazards=g.hazards.filter(h=>h.x>-60);if(g.t>=duration){const r=Math.hypot(g.x-760,g.y-250);if(r<70){end(false,'Your spacecraft entered the planet collision zone. Aim for the glowing orbital band, not the surface.');return}g.orbit=r>=90&&r<=145?g.orbit+dt:Math.max(0,g.orbit-dt*.7);if(g.orbit>=GAME_BALANCE.holdSeconds){end(true);return}}}
 c.fillStyle='#0a1022';c.fillRect(0,0,1000,500);for(const s of stars){c.fillStyle='#7b8eae';c.fillRect((s.x-g.t*12+10000)%1000,s.y,2,2)}c.strokeStyle='#1b2541';c.lineWidth=1;for(let x=0;x<1000;x+=50){c.beginPath();c.moveTo(x,0);c.lineTo(x,500);c.stroke()}for(let y=0;y<500;y+=50){c.beginPath();c.moveTo(0,y);c.lineTo(1000,y);c.stroke()}
 // Illustrative heliocentric ellipse retains the NASA eccentricity; mean motion uses period.
 const o=NASA_ORRERY_DATA[selected],r=35,b=r*Math.sqrt(1-o.eccentricity**2),M=(g.t*40/o.period)*Math.PI*2;let E=M;for(let i=0;i<5;i++)E=M+o.eccentricity*Math.sin(E);c.strokeStyle='#546382';c.beginPath();c.ellipse(66,66,r,b,0,0,Math.PI*2);c.stroke();c.fillStyle='#e9c57b';c.fillRect(66-r*o.eccentricity-2,64,4,4);c.fillStyle=world()[2];c.fillRect(64+r*Math.cos(E),64+b*Math.sin(E),4,4);c.font='9px monospace';c.fillStyle='#7d8ba6';c.fillText('ORRERY · SCHEMATIC',18,120);
 if(g.t>=duration-3){c.strokeStyle='#68e8df';c.lineWidth=2;c.setLineDash([7,7]);c.beginPath();c.arc(760,250,118,0,Math.PI*2);c.stroke();c.setLineDash([]);c.fillStyle='#7be7dc12';c.beginPath();c.arc(760,250,145,0,Math.PI*2);c.arc(760,250,90,0,Math.PI*2,true);c.fill();c.drawImage(planetSprite,673,177,174,145);c.fillStyle='#b6ccdd';c.font='12px monospace';c.fillText(selected.toUpperCase()+' / ORBITAL CAPTURE',650,435)}
 for(const h of g.hazards){if(h.comet){c.fillStyle='#b5daff44';c.beginPath();c.moveTo(h.x,h.y-7);c.lineTo(h.x+70,h.y-20);c.lineTo(h.x+15,h.y+7);c.fill()}c.fillStyle=h.comet?'#b9ebee':'#797c96';c.fillRect(h.x-h.r,h.y-h.r,h.r*1.8,h.r*1.7);c.fillStyle='#4e526c';c.fillRect(h.x-3,h.y-4,h.r*.7,h.r*.6)}rocket(c,g.x,g.y,Math.PI/2,1);if(g.paused){c.fillStyle='#080c1dc9';c.fillRect(0,0,1000,500);c.textAlign='center';c.fillStyle='#85e9e8';c.font='24px monospace';c.fillText(g.t===0?'YOUR MISSION STARTS HERE':'FLIGHT PAUSED',500,222);c.font='13px monospace';c.fillStyle='#b6c2dc';c.fillText('Steer through space, then hold the cyan orbital band.',500,260);c.fillText('Select '+(g.t===0?'START FLIGHT':'RESUME')+' below to continue.',500,288);c.textAlign='left'}$('#flight-status').textContent=g.paused?'AWAITING PILOT':g.t<duration?'EN ROUTE / '+selected.toUpperCase():'HOLD THE ORBITAL BAND';$('#flight-progress').textContent='TRANSIT '+Math.min(100,Math.floor(g.t/duration*100))+'%';$('#orbit-progress').textContent='ORBIT '+g.orbit.toFixed(1)+' / 5 s';frame=requestAnimationFrame(tick)}frame=requestAnimationFrame(tick)}
function results(){const facts=NASA_FACTS[selected];$('#screen').innerHTML=`<div class="results-hero"><div class="badge">✧</div><div class="label" style="margin-top:20px">ORBIT ESTABLISHED · SCIENCE LINK ACTIVE</div><h2>A little farther. A lot wiser.</h2><p>Your ${selected} mission is complete. Explore the NASA facts unlocked by your payload.</p><div class="tag" style="display:inline-block;color:var(--cyan)">EXPLORER SPONSOR BADGE · +${GAME_BALANCE.bonus} GAME CREDITS FOR FUTURE MISSIONS</div></div><div class="discoveries">${parts.instruments.map(i=>{const p=GAME_BALANCE.instruments[i];let title,value,description;if(p.kind==='camera'){title='A world in perspective';value=fmt(facts[0])+' km';description='Planetary diameter. Imaging supports studies of surfaces, clouds, or rings, depending on the destination.'}if(p.kind==='thermal'){title='The thermal picture';value=facts[2]+' °C';description='NASA fact-sheet mean temperature. Orbital thermal observations vary by location and atmospheric conditions; this is not a new reading.'}if(p.kind==='magnetic'){title='A magnetic signature';value=facts[3];description='Global magnetic field reported by the NASA fact sheet. “No” means no global field; local fields may still exist. “Unknown” is not evidence of absence.'}return`<article class="panel"><div class="label">${p.name.toUpperCase()}</div><h3>${title}</h3><strong>${value}</strong><p>${description}</p><a href="${SOURCES.facts}" target="_blank" rel="noopener">Verify NASA fact sheet ↗</a></article>`}).join('')}</div><div class="notice">These are existing NASA reference facts unlocked for learning, not newly simulated scientific discoveries. Sponsor badges and credits are fictional game rewards; no real organization is endorsing this mission.</div><div class="actions"><button class="primary" id="next-mission">Plan another mission ↗</button><button class="secondary" id="view-archive">Flight archive</button></div>`;$('#next-mission').onclick=()=>go(0);$('#view-archive').onclick=archive}
function modal(html){$('#modal-content').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
function notes(){if(game&&!game.ended){game.paused=true;$('#pause').textContent='Resume ▷'}modal(`<div class="label">OPEN SCIENCE / SOURCE MANIFEST</div><h2>Real data. Transparent rules.</h2><p>All planetary reference values live at the top of <strong>app.js</strong> in NASA_ORRERY_DATA and NASA_FACTS. There are no external libraries, data APIs, or runtime downloads.</p><ul><li><a href="${SOURCES.orrery}" target="_blank" rel="noopener">NASA ontology-based orrery</a>: exact orbital rows; semi-major axis in AU and period in days. The small flight diagram preserves eccentricity and relative mean motion. Orbit phases are illustrative, not current ephemerides. Planet sprites are schematic pixel art.</li><li><a href="${SOURCES.facts}" target="_blank" rel="noopener">NASA planetary fact sheet</a>: diameter, gravity, mean temperature, and global magnetic field. No moon counts are cached.</li><li><a href="${SOURCES.science}" target="_blank" rel="noopener">NASA Solar System Exploration</a>: world categories and educational descriptions. Pluto is a dwarf planet; Uranus and Neptune are ice giants.</li><li><a href="${SOURCES.data}" target="_blank" rel="noopener">NASA planetary data directory</a>: explore repositories for actual planetary observations.</li><li><a href="${SOURCES.trajectory}" target="_blank" rel="noopener">NASA Ames Trajectory Browser</a>: real trajectory search uses encounter type, launch window, duration, and ΔV. This offline game does not query it or claim NASA trajectory validation.</li></ul><h3>Distance calculation</h3><p>Displayed distance = |target semi-major axis − Earth semi-major axis| AU. This is the separation of mean circular orbits on the same side of the Sun. It is neither today's Earth distance nor an actual travel distance. Real separation varies with both planets' positions.</p><h3>Engineering rules</h3><p>Cost ≤ available budget; range proxy ≥ distance proxy; engine thrust ≥ total component weight; at least one science instrument. Credits, range ratings, weights, thrust ratings, sponsor rewards, five-second orbit holds, and hazard density are game balancing values stored separately in GAME_BALANCE. They are not NASA mission metrics. Weight and thrust use compatible abstract force units.</p><h3>Arcade flight</h3><p>Farther destinations get longer flights and faster hazards. Only Jupiter, Saturn, and Pluto routes include a dense arcade asteroid-belt encounter. These are obstacles along the route, not belts orbiting the planets. An orbital hold requires staying in the cyan band for five seconds; this is a piloting exercise, not orbital mechanics. Pausing stops the clock.</p><table><tr><th>World</th><th>Semi-major axis / AU</th><th>Period / days</th></tr>${Object.entries(NASA_ORRERY_DATA).map(([k,v])=>`<tr><td>${k}</td><td>${v.sma}</td><td>${v.period}</td></tr>`).join('')}</table>`)}
function archive(){if(game&&!game.ended){game.paused=true;$('#pause').textContent='Resume ▷'}modal(`<div class="label">YOUR EXPLORATION LOG</div><h2>Flight archive</h2>${history.length?`<p>${history.length} completed missions · ${bonus()} bonus game credits. Saved in this browser.</p><table><tr><th>Destination</th><th>Completed</th><th>Badge</th></tr>${[...history].reverse().map(h=>`<tr><td>${h.planet}</td><td>${Number.isNaN(Date.parse(h.date))?'Date unavailable':new Date(h.date).toLocaleDateString()}</td><td>✧ Explorer</td></tr>`).join('')}</table>`:'<p class="empty">Your story starts at the launch pad.<br>Complete a mission to earn your first Explorer badge.</p>'}`)}
document.addEventListener('keydown',e=>{if(!game||game.ended||$('#modal').open)return;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','w','a','s','d','p','P'].includes(e.key)){e.preventDefault();if((e.key==='p'||e.key==='P')&&!e.repeat)$('#pause').click();else keys[e.key]=true}});document.addEventListener('keyup',e=>keys[e.key]=false);window.addEventListener('blur',()=>{keys={};if(game&&!game.ended){game.paused=true;if($('#pause'))$('#pause').textContent='Resume ▷'}});document.addEventListener('visibilitychange',()=>{if(document.hidden){keys={};if(game&&!game.ended){game.paused=true;if($('#pause'))$('#pause').textContent='Resume ▷'}}});$('.close').onclick=()=>$('#modal').close();$('#sources-nav').onclick=$('#method-footer').onclick=notes;$('#archive-nav').onclick=archive;$('#mission-nav').onclick=()=>go(0);document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{const s=+b.dataset.step;if(s===0||s===1)go(s);else if(s===2&&checks().every(c=>c.ok))go(2);else if(s===3&&step===3)return;else modal('<h2>One step at a time.</h2><p>Complete the rocket checks and orbital flight to unlock your discoveries.</p>')});render();
